  'phalcon:database/Db/Dialect/DescribeReferencesTest#1' => 'SELECT c.relname AS TABLE_NAME, a.attname AS COLUMN_NAME, con.conname AS CONSTRAINT_NAME, current_database() AS REFERENCED_TABLE_SCHEMA, fc.relname AS REFERENCED_TABLE_NAME, fa.attname AS REFERENCED_COLUMN_NAME, CASE con.confupdtype WHEN \'c\' THEN \'CASCADE\' WHEN \'n\' THEN \'SET NULL\' WHEN \'d\' THEN \'SET DEFAULT\' WHEN \'r\' THEN \'RESTRICT\' WHEN \'a\' THEN \'NO ACTION\' END AS UPDATE_RULE, CASE con.confdeltype WHEN \'c\' THEN \'CASCADE\' WHEN \'n\' THEN \'SET NULL\' WHEN \'d\' THEN \'SET DEFAULT\' WHEN \'r\' THEN \'RESTRICT\' WHEN \'a\' THEN \'NO ACTION\' END AS DELETE_RULE FROM pg_catalog.pg_constraint AS con JOIN pg_catalog.pg_class AS c ON c.oid = con.conrelid JOIN pg_catalog.pg_namespace AS n ON n.oid = c.relnamespace JOIN pg_catalog.pg_class AS fc ON fc.oid = con.confrelid CROSS JOIN LATERAL unnest(con.conkey, con.confkey) WITH ORDINALITY AS k(colnum, refcolnum, colpos) JOIN pg_catalog.pg_attribute AS a ON a.attrelid = con.conrelid AND a.attnum = k.colnum JOIN pg_catalog.pg_attribute AS fa ON fa.attrelid = con.confrelid AND fa.attnum = k.refcolnum WHERE con.contype = \'f\' AND n.nspname = \'schema\' AND c.relname = \'table\' ORDER BY con.conname, k.colpos',
